// AfterQueryHook is called after Term is retrieved from the database
func (o *Term) AfterQueryHook(ctx context.Context, exec bob.Executor, queryType bob.QueryType) error {
	var err error

	switch queryType {
	case bob.QueryTypeSelect:
		ctx, err = Terms.AfterSelectHooks.RunHooks(ctx, exec, TermSlice{o})
	case bob.QueryTypeInsert:
		ctx, err = Terms.AfterInsertHooks.RunHooks(ctx, exec, TermSlice{o})
	case bob.QueryTypeUpdate:
		ctx, err = Terms.AfterUpdateHooks.RunHooks(ctx, exec, TermSlice{o})
	case bob.QueryTypeDelete:
		ctx, err = Terms.AfterDeleteHooks.RunHooks(ctx, exec, TermSlice{o})

	}

	return err
}

// primaryKeyVals returns the primary key values of the Term
func (o *Term) primaryKeyVals() bob.Expression {
	return sqlite.Arg(o.ID)
}

func (o *Term) pkEQ() dialect.Expression {
	return sqlite.Quote("terms", "id").EQ(bob.ExpressionFunc(func(ctx context.Context, w io.StringWriter, d bob.Dialect, start int) ([]any, error) {
		return o.primaryKeyVals().WriteSQL(ctx, w, d, start)
	}))
}

// Update uses an executor to update the Term
func (o *Term) Update(ctx context.Context, exec bob.Executor, s *TermSetter) error {
	v, err := Terms.Update(s.UpdateMod(), um.Where(o.pkEQ())).One(ctx, exec)
	if err != nil {
		return err
	}

	o.R = v.R
	*o = *v

	return nil
}

