type termWhere[Q sqlite.Filterable] struct {
	cols               termColumns
	ID                 sqlite.WhereMod[Q, string]
	CreatedAt          sqlite.WhereMod[Q, time.Time]
	UpdatedAt          sqlite.WhereMod[Q, time.Time]
	TermSetID          sqlite.WhereMod[Q, string]
	ParentID           sqlite.WhereNullMod[Q, string]
	Name               sqlite.WhereMod[Q, string]
	NormalizedName     sqlite.WhereMod[Q, string]
	Labels             sqlite.WhereMod[Q, types.JSON[map[string]string]]
	Synonyms           sqlite.WhereMod[Q, types.JSON[[]string]]
	Description        sqlite.WhereMod[Q, string]
	Color              sqlite.WhereNullMod[Q, string]
	SortOrder          sqlite.WhereMod[Q, int64]
	Path               sqlite.WhereMod[Q, string]
	MergedIntoID       sqlite.WhereNullMod[Q, string]
	AvailableAsKeyword sqlite.WhereMod[Q, bool]
	Deprecated         sqlite.WhereMod[Q, bool]
	Version            sqlite.WhereMod[Q, int64]
	R                  termWhereR[Q]
}

func (termWhere[Q]) AliasedAs(alias string) termWhere[Q] {
	return buildTermWhere[Q](buildTermColumns(alias))
}

func buildTermWhere[Q sqlite.Filterable](cols termColumns) termWhere[Q] {
	return termWhere[Q]{
		cols:               cols,
		ID:                 sqlite.Where[Q, string](cols.ID.Expression),
		CreatedAt:          sqlite.Where[Q, time.Time](cols.CreatedAt.Expression),
		UpdatedAt:          sqlite.Where[Q, time.Time](cols.UpdatedAt.Expression),
		TermSetID:          sqlite.Where[Q, string](cols.TermSetID.Expression),
		ParentID:           sqlite.WhereNull[Q, string](cols.ParentID.Expression),
		Name:               sqlite.Where[Q, string](cols.Name.Expression),
		NormalizedName:     sqlite.Where[Q, string](cols.NormalizedName.Expression),
		Labels:             sqlite.Where[Q, types.JSON[map[string]string]](cols.Labels.Expression),
		Synonyms:           sqlite.Where[Q, types.JSON[[]string]](cols.Synonyms.Expression),
		Description:        sqlite.Where[Q, string](cols.Description.Expression),
		Color:              sqlite.WhereNull[Q, string](cols.Color.Expression),
		SortOrder:          sqlite.Where[Q, int64](cols.SortOrder.Expression),
		Path:               sqlite.Where[Q, string](cols.Path.Expression),
		MergedIntoID:       sqlite.WhereNull[Q, string](cols.MergedIntoID.Expression),
		AvailableAsKeyword: sqlite.Where[Q, bool](cols.AvailableAsKeyword.Expression),
		Deprecated:         sqlite.Where[Q, bool](cols.Deprecated.Expression),
		Version:            sqlite.Where[Q, int64](cols.Version.Expression),
		R:                  termWhereR[Q]{cols: cols},
	}
}

// termWhereR holds the relationship-based filters of
// termWhere under the R namespace — mirroring the model's
// R struct — so they cannot collide with column-based filter fields.
type termWhereR[Q sqlite.Filterable] struct {
	cols termColumns
}

// HasIDRelationshipType filters parents that have a matching IDRelationshipType using a
// correlated EXISTS subquery (semi-join). Unlike an INNER JOIN it does not
// multiply parent rows, so no DISTINCT is needed. The optional filters are
// applied to the subquery (i.e. to RelationshipTypes).
func (w termWhereR[Q]) HasIDRelationshipType(filters ...bob.Mod[*dialect.SelectQuery]) mods.Where[Q] {
	q := sqlite.Select(
		sm.Columns(sqlite.Raw("1")),
		sm.From(RelationshipTypes.NameExpr()),
		sm.Where(RelationshipTypes.Columns.ID.EQ(w.cols.ID)),
	)
	q.Apply(filters...)
	return mods.Where[Q]{E: sqlite.Exists(q)}
}

// HasMergedInto filters parents that have a matching MergedInto using a
// correlated EXISTS subquery (semi-join). Unlike an INNER JOIN it does not
// multiply parent rows, so no DISTINCT is needed. The optional filters are
// applied to the subquery (i.e. to Terms).
func (w termWhereR[Q]) HasMergedInto(filters ...bob.Mod[*dialect.SelectQuery]) mods.Where[Q] {
	// self-referential relation: alias the subquery table so the correlation
	// columns still reference the parent row rather than the subquery's own row.
	relTbl := Terms.Columns.AliasedAs("MergedInto")
	q := sqlite.Select(
		sm.Columns(sqlite.Raw("1")),
		sm.From(Terms.NameExpr().As("MergedInto")),
		sm.Where(relTbl.ID.EQ(w.cols.MergedIntoID)),
	)
	q.Apply(filters...)
	return mods.Where[Q]{E: sqlite.Exists(q)}
}

