// HasItemSurfaces filters parents that have a matching ItemSurfaces (a
// many-to-many relationship) using a correlated EXISTS subquery instead of
// INNER JOINs, so the parent rows are not multiplied. The optional filters are
// applied to the subquery (i.e. to ItemSurfaces).
func (w termWhereR[Q]) HasItemSurfaces(filters ...bob.Mod[*dialect.SelectQuery]) mods.Where[Q] {
	q := sqlite.Select(
		sm.Columns(sqlite.Raw("1")),
		sm.From(ItemSurfaceKeywords.NameExpr()),
		sm.InnerJoin(ItemSurfaces.NameExpr()).On(
			ItemSurfaces.Columns.ID.EQ(ItemSurfaceKeywords.Columns.SurfaceID),
		),
		sm.Where(ItemSurfaceKeywords.Columns.Keyword.EQ(w.cols.ID)),
	)
	q.Apply(filters...)
	return mods.Where[Q]{E: sqlite.Exists(q)}
}

// HasResources filters parents that have a matching Resources (a
// many-to-many relationship) using a correlated EXISTS subquery instead of
// INNER JOINs, so the parent rows are not multiplied. The optional filters are
// applied to the subquery (i.e. to Resources).
func (w termWhereR[Q]) HasResources(filters ...bob.Mod[*dialect.SelectQuery]) mods.Where[Q] {
	q := sqlite.Select(
		sm.Columns(sqlite.Raw("1")),
		sm.From(ResourceKeywords.NameExpr()),
		sm.InnerJoin(Resources.NameExpr()).On(
			Resources.Columns.ID.EQ(ResourceKeywords.Columns.ResourceID),
		),
		sm.Where(ResourceKeywords.Columns.Keyword.EQ(w.cols.ID)),
	)
	q.Apply(filters...)
	return mods.Where[Q]{E: sqlite.Exists(q)}
}
